package sample.cafekiosk.learning;

class GuavaLearningTest {

    @DisplayName("partition 은 나머지를 마지막 조각에 남긴다")
    @Test
    void partitionRemainder() {
        // given
        List<Integer> list = List.of(1, 2, 3, 4, 5);

        // when
        List<List<Integer>> result = Lists.partition(list, 2);

        // then
        assertThat(result).hasSize(3)
                .containsExactly(List.of(1, 2), List.of(3, 4), List.of(5));
    }

    @DisplayName("partition 결과는 원본을 들여다보는 뷰다")
    @Test
    void partitionIsView() {
        // given
        List<Integer> list = new ArrayList<>(List.of(1, 2, 3, 4));
        List<List<Integer>> result = Lists.partition(list, 2);

        // when
        list.set(0, 99);

        // then
        assertThat(result.get(0)).containsExactly(99, 2);
    }
}

