# --- 잭슨을 익힌다 ---

class JacksonLearningTest {

    private final ObjectMapper objectMapper = new ObjectMapper()
            .registerModule(new JavaTimeModule())
            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

    @DisplayName("LocalDateTime 은 ISO 문자열로 직렬화된다")
    @Test
    void serializeLocalDateTime() throws Exception {
        // given
        var order = new OrderResponse(1L, LocalDateTime.of(2026, 9, 9, 11, 0));

        // when
        String json = objectMapper.writeValueAsString(order);

        // then
        assertThat(json).isEqualTo(
                "{\"id\":1,\"registeredDateTime\":\"2026-09-09T11:00:00\"}");
    }

    @DisplayName("모르는 필드가 오면 예외가 난다")
    @Test
    void unknownProperty() {
        // given
        String json = "{\"id\":1,\"nickname\":\"x\"}";

        // when & then
        assertThatThrownBy(() -> objectMapper.readValue(json, OrderResponse.class))
                .isInstanceOf(UnrecognizedPropertyException.class);
    }
}

